from taf.cloud.cbam.interfaces.cbam_base import CBAM
from taf.cloud.cbam.vnf.v4.vnf import VNF4
from taf.cloud.cbam.catalog.v18.catalog import Catalog18
from taf.cloud.cbam.exception import VnfmApiNotSupported


class CBAM19(CBAM):
    supported_vnfs = {'4.0': VNF4}

    def __init__(self, ip, client_id, client_secret, verify, vnfm_api_version):
        super(CBAM19, self).__init__(ip, client_id, client_secret, verify)

        self.catalog = Catalog18(session=self._session)
        if vnfm_api_version is not None:
            if vnfm_api_version not in self.supported_vnfs:
                exc_msg = "VNFM API in version {} is not supported."
                exc_msg = exc_msg.format(vnfm_api_version)
                raise VnfmApiNotSupported(exc_msg)
            vnf_type = self.supported_vnfs[vnfm_api_version]
            self.vnf = vnf_type(session=self._session, api_version=vnfm_api_version)
        else:
            self.vnf = VNF4(session=self._session)
